<div class="admin-toolbar mb-3"><form method="get" class="row g-2 align-items-end"><div class="col-md-2"><label class="form-label small">Fecha</label><input type="date" name="date" class="form-control form-control-sm" value="<?php echo htmlspecialchars($workDate); ?>"></div><div class="col-md-2"><label class="form-label small">Sucursal</label><select name="branch_id" class="form-select form-select-sm"><option value="0">Todas</option><?php foreach($data['branches'] as $b): ?><option value="<?php echo (int)$b->id; ?>" <?php echo (int)$data['branch_id']===(int)$b->id?'selected':''; ?>><?php echo htmlspecialchars($b->name); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label small">Empleado</label><select name="user_id" class="form-select form-select-sm"><option value="0">Todos</option><?php foreach($data['employees'] as $u): ?><option value="<?php echo (int)$u->id; ?>" <?php echo (int)$data['user_id_filter']===(int)$u->id?'selected':''; ?>><?php echo htmlspecialchars($u->full_name); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label small">Estado</label><select name="status" class="form-select form-select-sm"><?php foreach(['alerts'=>'Solo alertas','all'=>'Todos','ok'=>'En horario','late'=>'Tarde','no_show'=>'Sin fichada','flexible'=>'Control flexible','no_clock'=>'Sin reloj','on_leave'=>'Licencia'] as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $status===$key?'selected':''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-primary btn-sm">Filtrar</button></div></form></div>
<div class="db-card p-0 overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0 admin-table"><thead><tr><th>Empleado / sucursal</th><th>Control</th><th>Planificado</th><th>Fichado / reloj</th><th>Δ</th><th>Estado</th><th></th></tr></thead><tbody><?php if(empty($rows)): ?><tr><td colspan="7" class="text-center text-muted py-4">Sin registros para estos filtros.</td></tr><?php else: foreach($rows as $row): ?><tr><td><strong><?php echo htmlspecialchars($row->full_name); ?></strong><div class="small text-muted"><?php echo htmlspecialchars($row->branch_name ?: 'Sin sucursal'); ?></div></td><td><span class="badge bg-<?php echo $row->attendance_control_mode==='required'?'primary':($row->attendance_control_mode==='flexible'?'info':'secondary'); ?>"><?php echo htmlspecialchars(User::attendanceControlOptions()[$row->attendance_control_mode]); ?></span></td><td class="small"><?php echo $row->planned_start ? attendanceFormatTime($row->planned_start).'–'.attendanceFormatTime($row->planned_end) : '—'; ?></td><td class="small"><?php echo attendanceFormatTime($row->actual_entry); ?><?php if($row->actual_exit): ?>–<?php echo attendanceFormatTime($row->actual_exit); ?><?php endif; ?><div class="text-muted"><?php echo htmlspecialchars($row->device_names ?: 'Sin reloj'); ?></div></td><td class="small <?php echo ($row->delta_minutes??0)>=0?'text-success':'text-danger'; ?>"><?php echo attendanceFormatMinutes($row->delta_minutes); ?></td><td><?php echo attendanceStatusBadge($row->status); ?></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="<?php echo URLROOT; ?>/admin/marcacionesTodas?person_q=<?php echo urlencode($row->full_name); ?>&start_date=<?php echo urlencode($workDate); ?>&end_date=<?php echo urlencode($workDate); ?>">Marcas</a><?php if(!in_array($row->status,['ok','on_leave','flexible','no_clock'],true)): ?><a class="btn btn-sm btn-outline-primary" href="<?php echo attendanceJustifyCalendarUrl($row->user_id,$workDate,$row->status); ?>">Justificar</a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
